import http from 'node:http';
import path from 'node:path';
import { FileJsDb } from '../file-db.js';
import { FELTDB_CONVERGENCE_COLLECTION, FeltDBProposalService } from '../proposal.js';
import { IntentService } from '../intent.js';
const DEVELOPMENT_CONTROL_PLANE_CAPABILITIES = {
    contract: 'feltdb.control-plane.capabilities',
    version: 1,
    capabilities: [
        { id: 'overview.instance', area: 'overview', title: 'Development authority overview', status: 'available', surface: ['GET /v1/control-plane/overview'], note: '' },
        { id: 'data.collections.list', area: 'data', title: 'List declared collections', status: 'available', surface: ['GET /v1/application/schema'], note: '' },
        { id: 'data.schema.inspect', area: 'data', title: 'Inspect the application schema', status: 'available', surface: ['GET /v1/application/schema'], note: '' },
        { id: 'data.records.browse', area: 'data', title: 'Browse records', status: 'available', surface: ['GET /v1/data/{collection}'], note: '' },
        { id: 'provenance.transactions', area: 'operations', title: 'Recent attributed transactions', status: 'unsupported', surface: [], note: 'Transaction observability is not available from the lightweight development authority.' },
        { id: 'replication.health', area: 'replication', title: 'Replication health', status: 'unsupported', surface: [], note: 'Replication health is not available from the lightweight development authority.' },
    ],
};
/** Start the durable, unauthenticated loopback authority used by `feltdb dev`. */
export async function startLocalDevelopmentAuthority(options) {
    const host = options.host || '127.0.0.1';
    const port = options.port ?? 7700;
    if (host !== '127.0.0.1' && host !== 'localhost' && host !== '::1') {
        throw new Error('The development authority may only bind to a loopback address');
    }
    const db = new FileJsDb(path.resolve(options.dataDir));
    const proposalAuthorityToken = crypto.randomUUID();
    const store = {
        async get(collection, id) { const result = db.get(`${collection}:${id}`); if (!result.success)
            throw new Error(result.error); return result.data ? JSON.parse(result.data) : undefined; },
        async list(collection) { const result = db.query(collection); if (!result.success)
            throw new Error(result.error); return JSON.parse(result.data || '[]'); },
        async create(collection, id, value) { const result = db.insert(`${collection}:${id}`, JSON.stringify(value)); if (!result.success)
            throw new Error(result.error); },
        async replace(collection, id, value) { const result = db.update(`${collection}:${id}`, JSON.stringify(value)); if (!result.success)
            throw new Error(result.error); },
    };
    const proposalService = options.proposalContext ? new FeltDBProposalService(store, options.proposalContext, proposalAuthorityToken) : undefined;
    const intentService = proposalService && options.proposalContext ? new IntentService(store, options.proposalContext, proposalService, options.intentObservations) : undefined;
    const streams = new Set();
    let endpoint = '';
    const server = http.createServer(async (request, response) => {
        try {
            response.setHeader('Access-Control-Allow-Origin', '*');
            response.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, OPTIONS');
            response.setHeader('Access-Control-Allow-Headers', 'Authorization, Content-Type, FeltDB-Protocol, FeltDB-Proposal-Authority');
            response.setHeader('Cache-Control', 'no-store');
            if (request.method === 'OPTIONS') {
                response.statusCode = 204;
                response.end();
                return;
            }
            const requestUrl = new URL(request.url || '/', `http://${host}`);
            const pathname = requestUrl.pathname;
            if (request.method === 'GET' && (pathname === '/health' || pathname === '/ready')) {
                json(response, 200, { status: 'ready', storage: 'writable', authority: 'local-development' });
                return;
            }
            if (request.method === 'GET' && pathname === '/events') {
                response.writeHead(200, {
                    'Content-Type': 'text/event-stream',
                    Connection: 'keep-alive',
                    'Cache-Control': 'no-cache',
                    'Access-Control-Allow-Origin': '*',
                });
                response.write(': connected\n\n');
                streams.add(response);
                request.once('close', () => streams.delete(response));
                return;
            }
            if (request.method === 'GET' && pathname === '/v1/application/schema') {
                if (!options.proposalContext) {
                    json(response, 503, { code: 'application_contract_unavailable', message: 'The development application contract is unavailable.' });
                    return;
                }
                const { snapshot } = await options.proposalContext();
                const collections = snapshot.schema.map(collection => {
                    const direct = collection.fields.flatMap(field => field.reference ? [{
                            name: field.name,
                            source_collection: collection.name,
                            target_collection: field.reference,
                            cardinality: 'one',
                            foreign_field: field.name,
                        }] : []);
                    const reverse = snapshot.schema.flatMap(source => source.fields.flatMap(field => field.reference === collection.name ? [{
                            name: `${source.name}_${field.name}`,
                            source_collection: source.name,
                            target_collection: collection.name,
                            cardinality: 'many',
                            foreign_field: field.name,
                        }] : []));
                    return { collection: collection.name, description: '', fields: collection.fields, relationships: [...direct, ...reverse] };
                });
                json(response, 200, {
                    application: snapshot.application,
                    contract_version: snapshot.contract_version,
                    collections,
                    capabilities: snapshot.capabilities,
                    workflows: snapshot.workflows,
                    agents: snapshot.agents,
                    policies: snapshot.policies,
                });
                return;
            }
            if (request.method === 'GET' && pathname === '/v1/control-plane/capabilities') {
                json(response, 200, DEVELOPMENT_CONTROL_PLANE_CAPABILITIES);
                return;
            }
            if (request.method === 'GET' && pathname === '/v1/control-plane/overview') {
                const context = options.runtimeContext;
                const authorityState = db.authorityStateSummary();
                json(response, 200, {
                    instance: {
                        instance_id: db.instance_id(),
                        namespace: context?.namespace ?? 'default',
                        runtime: context?.runtime ?? 'node',
                        storage: context?.storage ?? 'durable',
                        distributed: context?.distributed ?? false,
                        application_lifecycle: context?.applicationLifecycle ?? 'attached',
                        application_url: context?.applicationUrl ?? null,
                    },
                    authority: {
                        kind: 'local-development',
                        advertise_url: endpoint,
                        state_version: authorityState.current_sequence,
                    },
                    authority_state: authorityState,
                    storage: {
                        records: authorityState.records,
                        collections: authorityState.collections,
                    },
                });
                return;
            }
            const dataMatch = pathname.match(/^\/v1\/data\/([^/]+)$/);
            if (request.method === 'GET' && dataMatch) {
                if (!options.proposalContext) {
                    json(response, 503, { code: 'application_contract_unavailable', message: 'The development application contract is unavailable.' });
                    return;
                }
                const { snapshot } = await options.proposalContext();
                const collection = decodeURIComponent(dataMatch[1]);
                if (!snapshot.schema.some(value => value.name === collection)) {
                    json(response, 404, { code: 'collection_not_found', message: `Collection ${collection} is not declared by this application.` });
                    return;
                }
                const requestedLimit = Number(requestUrl.searchParams.get('limit') || 50);
                if (!Number.isInteger(requestedLimit) || requestedLimit < 1) {
                    json(response, 422, { code: 'invalid_limit', message: 'limit must be a positive integer.' });
                    return;
                }
                const limit = Math.min(requestedLimit, 100);
                const stateVersion = db.get_sequence();
                let offset = 0;
                const cursor = requestUrl.searchParams.get('cursor');
                if (cursor) {
                    try {
                        const decoded = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
                        if (decoded.v !== 1 || decoded.collection !== collection || decoded.state !== stateVersion
                            || !Number.isInteger(decoded.offset) || (decoded.offset ?? -1) < 0)
                            throw new Error('invalid cursor');
                        offset = decoded.offset;
                    }
                    catch {
                        json(response, 422, { code: 'invalid_cursor', message: 'The cursor is invalid, stale, or belongs to another collection.' });
                        return;
                    }
                }
                const result = db.query(collection);
                if (!result.success) {
                    json(response, 500, { code: 'authority_read_failed', message: result.error });
                    return;
                }
                const records = JSON.parse(result.data || '[]')
                    .sort((left, right) => String(left.id ?? JSON.stringify(left)).localeCompare(String(right.id ?? JSON.stringify(right))));
                const page = records.slice(offset, offset + limit);
                const nextOffset = offset + page.length;
                const nextCursor = nextOffset < records.length
                    ? Buffer.from(JSON.stringify({ v: 1, collection, state: stateVersion, offset: nextOffset })).toString('base64url')
                    : null;
                json(response, 200, {
                    collection,
                    records: page,
                    pagination: { limit, nextCursor },
                    state_version: stateVersion,
                });
                return;
            }
            const previewSimulationMatch = pathname.match(/^\/v1\/previews\/([^/]+)\/simulate$/);
            if (previewSimulationMatch) {
                if (!proposalService) {
                    json(response, 503, { error: 'PROPOSAL_SERVICE_UNAVAILABLE' });
                    return;
                }
                if (request.method !== 'POST') {
                    json(response, 405, { error: 'METHOD_NOT_ALLOWED' });
                    return;
                }
                const artifact = await proposalService.getPreview(decodeURIComponent(previewSimulationMatch[1]));
                const input = parseObject(await readBody(request));
                const event = String(input.event || '');
                if (!artifact.events.includes(event)) {
                    json(response, 422, { error: 'UNSUPPORTED_PREVIEW_EVENT' });
                    return;
                }
                json(response, 200, { preview_id: artifact.preview_id, event, status: 'simulated', external_side_effects: 'none', trace: artifact.state_flow, writes: 'isolated_preview_namespace_only' });
                return;
            }
            const previewMatch = pathname.match(/^\/v1\/previews\/([^/]+)(?:\/data\/([^/]+))?$/);
            if (previewMatch) {
                if (!proposalService) {
                    json(response, 503, { error: 'PROPOSAL_SERVICE_UNAVAILABLE' });
                    return;
                }
                const artifact = await proposalService.getPreview(decodeURIComponent(previewMatch[1]));
                if (request.method === 'GET' && !previewMatch[2]) {
                    json(response, 200, artifact);
                    return;
                }
                if (request.method === 'GET' && previewMatch[2]) {
                    const collection = decodeURIComponent(previewMatch[2]);
                    const seed = artifact.seeded_records.find(value => value.collection === collection);
                    json(response, seed ? 200 : 404, seed ? { preview_id: artifact.preview_id, collection, records: [{ id: seed.id, _preview_data: true, _preview_source: 'synthetic' }], data_classification: 'synthetic_preview', pagination: { limit: 50, nextCursor: null } } : { error: 'COLLECTION_NOT_FOUND' });
                    return;
                }
                json(response, 405, { error: 'METHOD_NOT_ALLOWED' });
                return;
            }
            const intentMatch = pathname.match(/^\/v1\/intents(?:\/([^/]+)(?:\/(understanding|plan|proposal|history|execute))?)?$/);
            if (intentMatch) {
                if (!intentService) {
                    json(response, 503, { error: 'INTENT_SERVICE_UNAVAILABLE' });
                    return;
                }
                const id = intentMatch[1] ? decodeURIComponent(intentMatch[1]) : undefined;
                const operation = intentMatch[2];
                const body = await readBody(request);
                const input = body ? parseObject(body) : {};
                if (request.method === 'POST' && !id) {
                    const raw = String(input.raw_request ?? input.request ?? '');
                    json(response, 201, await intentService.execute(raw, String(input.actor ?? 'developer')));
                    return;
                }
                if (request.method === 'GET' && !id) {
                    json(response, 200, { intents: await intentService.list() });
                    return;
                }
                if (request.method === 'GET' && id) {
                    const intent = await intentService.get(id);
                    if (!operation) {
                        json(response, 200, intent);
                        return;
                    }
                    if (operation === 'understanding') {
                        json(response, 200, intent.understanding ?? {});
                        return;
                    }
                    if (operation === 'plan') {
                        json(response, 200, intent.plan ?? {});
                        return;
                    }
                    if (operation === 'proposal') {
                        json(response, 200, intent.proposal_id ? await proposalService.get(intent.proposal_id) : {});
                        return;
                    }
                    if (operation === 'history') {
                        json(response, 200, { events: await intentService.history(id) });
                        return;
                    }
                }
                json(response, 405, { error: 'METHOD_NOT_ALLOWED' });
                return;
            }
            const proposalMatch = pathname.match(/^\/v1\/proposals(?:\/([^/]+)(?:\/(validate|preview|approve|reject|status|history|convergence))?)?$/);
            if (proposalMatch) {
                if (!proposalService) {
                    json(response, 503, { error: 'PROPOSAL_SERVICE_UNAVAILABLE' });
                    return;
                }
                const id = proposalMatch[1] ? decodeURIComponent(proposalMatch[1]) : undefined;
                const operation = proposalMatch[2];
                const body = await readBody(request);
                const input = body ? parseObject(body) : {};
                const actor = typeof input.actor === 'string' ? input.actor : 'local-developer';
                if (request.method === 'POST' && !id) {
                    json(response, 201, await proposalService.create(input));
                    return;
                }
                if (request.method === 'GET' && !id) {
                    const limit = Math.max(1, Math.min(100, Number(requestUrl.searchParams.get('limit') || 50)));
                    const status = requestUrl.searchParams.get('status');
                    const environment = requestUrl.searchParams.get('environment');
                    const after = requestUrl.searchParams.get('cursor');
                    const offset = after ? Number(Buffer.from(after, 'base64url').toString('utf8')) : 0;
                    const all = (await proposalService.list()).filter(value => (!status || value.status === status) && (!environment || value.environment === environment)).sort((a, b) => a.id.localeCompare(b.id));
                    const proposals = all.slice(offset, offset + limit);
                    const nextCursor = offset + limit < all.length ? Buffer.from(String(offset + limit)).toString('base64url') : null;
                    json(response, 200, { proposals, pagination: { limit, nextCursor } });
                    return;
                }
                if (request.method === 'GET' && id && !operation) {
                    json(response, 200, await proposalService.get(id));
                    return;
                }
                if (request.method === 'GET' && id && operation === 'history') {
                    json(response, 200, { events: await proposalService.history(id) });
                    return;
                }
                if (request.method === 'GET' && id && operation === 'status') {
                    json(response, 200, await proposalService.readiness(id));
                    return;
                }
                if (request.method === 'GET' && id && operation === 'convergence') {
                    const all = await store.list(FELTDB_CONVERGENCE_COLLECTION);
                    json(response, 200, { convergence: all.filter(value => value.proposal_id === id).sort((a, b) => String(b.created_at).localeCompare(String(a.created_at))) });
                    return;
                }
                if (request.method === 'POST' && id && operation === 'convergence') {
                    const proposal = await proposalService.get(id);
                    if (proposal.status !== 'applied')
                        throw new Error('PROPOSAL_NOT_APPLIED');
                    if (input.proposal_id !== id)
                        throw new Error('INVALID_CONVERGENCE');
                    const value = { ...input, id: `cv_${crypto.randomUUID().replaceAll('-', '')}`, created_at: new Date().toISOString(), verifier_version: 1 };
                    await store.create(FELTDB_CONVERGENCE_COLLECTION, value.id, value);
                    json(response, 201, value);
                    return;
                }
                if (request.method === 'POST' && id && operation === 'validate') {
                    json(response, 200, await proposalService.validate(id, actor));
                    return;
                }
                if (request.method === 'POST' && id && operation === 'preview') {
                    json(response, 200, await proposalService.preview(id, actor));
                    return;
                }
                if (request.method === 'POST' && id && operation === 'approve') {
                    json(response, 200, await proposalService.transition(id, 'approved', actor, undefined, input.approve_authorization === true));
                    return;
                }
                if (request.method === 'POST' && id && operation === 'reject') {
                    json(response, 200, await proposalService.transition(id, 'rejected', actor));
                    return;
                }
                if (request.method === 'PATCH' && id && operation === 'status') {
                    const status = String(input.status || '');
                    json(response, 200, await proposalService.transition(id, status, actor, request.headers['feltdb-proposal-authority'], input.approve_authorization === true));
                    return;
                }
                json(response, 405, { error: 'METHOD_NOT_ALLOWED' });
                return;
            }
            const match = pathname.match(/^\/collections\/([^/]+)(?:\/([^/]+))?$/);
            if (!match) {
                json(response, 404, { error: 'NOT_FOUND' });
                return;
            }
            const collection = decodeURIComponent(match[1]);
            if (collection.startsWith('_feltdb.')) {
                json(response, 403, { error: 'SYSTEM_COLLECTION_REQUIRES_SERVICE_API' });
                return;
            }
            const id = match[2] ? decodeURIComponent(match[2]) : undefined;
            const body = await readBody(request);
            let result;
            if (request.method === 'GET' && !id) {
                result = db.query(collection);
                json(response, result.success ? 200 : 500, result.success
                    ? JSON.parse(result.data || '[]').map(value => ({ value }))
                    : { error: result.error });
                return;
            }
            if (request.method === 'GET' && id) {
                result = db.get(`${collection}:${id}`);
                if (!result.success) {
                    json(response, 500, { error: result.error });
                    return;
                }
                if (!result.data) {
                    json(response, 404, { error: 'NOT_FOUND' });
                    return;
                }
                json(response, 200, { value: JSON.parse(result.data) });
                return;
            }
            if (request.method === 'POST' && !id) {
                const value = parseObject(body);
                const recordId = typeof value.id === 'string' ? value.id : '';
                if (!recordId) {
                    json(response, 400, { error: 'Record must have an id' });
                    return;
                }
                result = db.insert(`${collection}:${recordId}`, JSON.stringify(value));
            }
            else if (request.method === 'PATCH' && id) {
                result = db.update(`${collection}:${id}`, JSON.stringify(parseObject(body)));
            }
            else if (request.method === 'DELETE' && id) {
                result = db.delete(`${collection}:${id}`);
            }
            else {
                json(response, 404, { error: 'NOT_FOUND' });
                return;
            }
            if (!result.success) {
                json(response, 400, { error: result.error });
                return;
            }
            json(response, request.method === 'POST' ? 201 : 200, { ok: true });
            const frame = `data: ${JSON.stringify({ change: { capability: collection } })}\n\n`;
            for (const stream of streams)
                stream.write(frame);
        }
        catch (error) {
            if (!response.headersSent)
                json(response, 400, { error: error instanceof Error ? error.message : String(error) });
            else
                response.end();
        }
    });
    await new Promise((resolve, reject) => {
        server.once('error', reject);
        server.listen(port, host, resolve);
    });
    const address = server.address();
    if (!address || typeof address === 'string')
        throw new Error('Development authority did not expose a TCP address');
    endpoint = `http://${host}:${address.port}`;
    return {
        endpoint,
        proposalAuthorityToken,
        close: () => new Promise((resolve, reject) => {
            for (const stream of streams)
                stream.end();
            server.close(error => error ? reject(error) : resolve());
        }),
    };
}
function json(response, status, value) {
    response.statusCode = status;
    response.setHeader('Content-Type', 'application/json; charset=utf-8');
    response.end(JSON.stringify(value));
}
function readBody(request) {
    return new Promise((resolve, reject) => {
        let body = '';
        request.setEncoding('utf8');
        request.on('data', chunk => { body += chunk; });
        request.once('end', () => resolve(body));
        request.once('error', reject);
    });
}
function parseObject(body) {
    const value = JSON.parse(body || '{}');
    if (!value || typeof value !== 'object' || Array.isArray(value))
        throw new Error('Request body must be an object');
    return value;
}
